import type { ElementType, HTMLAttributes } from "react";
import { cx } from "../utils/cx";
import { Surface, type SurfaceProps } from "./surface";

export type CardProps = SurfaceProps;

/**
 * A titled block of content. Defaults to the studio's flat `section` material (a hairline above, no box); pass
 * `variant="outlined" | "elevated" | "glass" | "holo"` for a contained card.
 *
 *   <Card aria-labelledby="up"><CardHeader><CardTitle id="up">Upcoming</CardTitle><a href="/cal">Calendar</a></CardHeader>
 *     <CardContent>...</CardContent></Card>
 */
export function Card({ as = "section", className, ...rest }: CardProps) {
  return <Surface as={as} {...rest} className={cx("hm-card", className)} />;
}

/** Title row: the title on the left, a quiet link or meta on the right. */
export function CardHeader({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return <div {...rest} className={cx("hm-card-header", className)} />;
}

export function CardTitle({
  as: As = "h2",
  className,
  ...rest
}: HTMLAttributes<HTMLHeadingElement> & { as?: ElementType }) {
  return <As {...rest} className={cx("hm-card-title", className)} />;
}

export function CardDescription({ className, ...rest }: HTMLAttributes<HTMLParagraphElement>) {
  return <p {...rest} className={cx("hm-card-description", className)} />;
}

export function CardContent({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return <div {...rest} className={cx("hm-card-content", className)} />;
}

export function CardFooter({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return <div {...rest} className={cx("hm-card-footer", className)} />;
}
